-- Runs against the installed CRM using an existing administrator's JWT subject.
-- All fixtures and changes roll back. No email, payment or real booking is sent.
begin;
create temporary table crm_test_results(test text,passed boolean);
do $$
declare admin_id uuid; lead1 uuid; lead2 uuid; lead3 uuid; class1 uuid; class2 uuid; booking1 uuid; booking2 uuid; student1 uuid; student2 uuid; membership uuid; submission uuid:=gen_random_uuid(); rejected boolean; result jsonb;
begin
 select user_id into admin_id from public.cms_admins limit 1;
 if admin_id is null then raise exception 'An existing administrator is required for this test';end if;
 perform set_config('request.jwt.claim.sub','',true);
 begin perform public.crm_staff('load');raise exception 'Anonymous CRM read succeeded';exception when insufficient_privilege then null;end;
 insert into crm_test_results values('Anonymous staff RPC rejected',true);
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 begin perform public.crm_staff('load');raise exception 'Non-admin read succeeded';exception when insufficient_privilege then null;end;
 insert into crm_test_results values('Authenticated non-admin rejected',true);
 perform public.crm_trial_inquiry(jsonb_build_object('submission_id',submission,'name','CRM workflow test','email','crm-workflow-1@example.invalid','contact_method','Email','consent',true));
 perform public.crm_trial_inquiry(jsonb_build_object('submission_id',submission,'name','CRM workflow test','email','crm-workflow-1@example.invalid','consent',true));
 if (select count(*) from school_crm.leads where submission_id=submission)<>1 then raise exception 'Intake not idempotent';end if;
 select id into lead1 from school_crm.leads where submission_id=submission;
 insert into crm_test_results values('Public trial intake saved once',true);
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 lead2:=(public.crm_staff('lead_save','{"name":"Second test","email":"crm-workflow-2@example.invalid","contact_method":"Email","status":"New","source":"Manual","note":"Initial note"}')->>'id')::uuid;
 lead3:=(public.crm_staff('lead_save','{"name":"Returning test","email":"crm-workflow-1@example.invalid","contact_method":"Email","status":"New","source":"Manual"}')->>'id')::uuid;
 class1:=(public.crm_staff('class_save',jsonb_build_object('group_name','Newborn · test','class_type','Single partner group','instructor','Test instructor','room','Test room','starts_at',now()+interval '1 day','ends_at',now()+interval '1 day 1 hour','capacity',1))->>'id')::uuid;
 class2:=(public.crm_staff('class_save',jsonb_build_object('group_name','Toddler · test','class_type','Single partner group','instructor','Test instructor','room','Test room','starts_at',now()+interval '1 day 30 minutes','ends_at',now()+interval '1 day 90 minutes','capacity',2))->>'id')::uuid;
 booking1:=(public.crm_staff('book',jsonb_build_object('lead_id',lead1,'class_id',class1))->>'id')::uuid;
 if (select status from school_crm.leads where id=lead1)<>'Trial Booked' then raise exception 'Lead status not updated';end if;
 insert into crm_test_results values('Booking and lead status committed together',true);
 rejected:=false;begin perform public.crm_staff('book',jsonb_build_object('lead_id',lead2,'class_id',class1));exception when others then if sqlerrm='Class is full' then rejected:=true;else raise;end if;end;
 if not rejected then raise exception 'Full class accepted a booking';end if;
 insert into crm_test_results values('Full class rejects new booking',true);
 rejected:=false;begin perform public.crm_staff('book',jsonb_build_object('lead_id',lead1,'class_id',class1));exception when others then if sqlerrm='Already booked into this class' then rejected:=true;else raise;end if;end;
 if not rejected then raise exception 'Duplicate booking allowed';end if;
 insert into crm_test_results values('Duplicate booking rejected',true);
 rejected:=false;begin perform public.crm_staff('book',jsonb_build_object('lead_id',lead1,'class_id',class2));exception when others then if sqlerrm='This person already has an overlapping booking' then rejected:=true;else raise;end if;end;
 if not rejected then raise exception 'Overlapping booking allowed';end if;
 insert into crm_test_results values('Overlapping class rejected',true);
 perform public.crm_staff('attendance',jsonb_build_object('booking_id',booking1,'attendance','No-show'));
 booking2:=(public.crm_staff('book',jsonb_build_object('lead_id',lead1,'class_id',class2,'replace_booking',booking1))->>'id')::uuid;
 if (select status from school_crm.bookings where id=booking1)<>'Cancelled' then raise exception 'Reschedule did not cancel old booking';end if;
 perform public.crm_staff('book',jsonb_build_object('lead_id',lead2,'class_id',class1));
 insert into crm_test_results values('No-show, reschedule and released spot work',true);
 perform public.crm_staff('attendance',jsonb_build_object('booking_id',booking2,'attendance','Present'));
 if (select status from school_crm.leads where id=lead1)<>'Trial Attended' then raise exception 'Attendance did not update lead';end if;
 insert into crm_test_results values('Present attendee becomes Trial Attended',true);
 student1:=(public.crm_staff('convert',jsonb_build_object('lead_id',lead1,'group_name','Toddler'))->>'id')::uuid;
 student2:=(public.crm_staff('convert',jsonb_build_object('lead_id',lead1))->>'id')::uuid;
 if student1<>student2 then raise exception 'Repeated conversion duplicated student';end if;
 student2:=(public.crm_staff('convert',jsonb_build_object('lead_id',lead3))->>'id')::uuid;
 if student1<>student2 then raise exception 'Contact match did not reuse student';end if;
 insert into crm_test_results values('Repeated conversion and existing contact reuse same student',true);
 membership:=(public.crm_staff('membership',jsonb_build_object('student_id',student1,'plan','First Embrace','starts_on',current_date,'expires_on',current_date+27,'total_sessions',4,'remaining_sessions',4))->>'id')::uuid;
 if not exists(select 1 from school_crm.memberships where id=membership and remaining_sessions=4) then raise exception 'Membership missing';end if;
 if not exists(select 1 from school_crm.history where lead_id=lead1 and event='Converted') then raise exception 'History missing';end if;
 insert into crm_test_results values('Membership and dated history retained',true);
 perform public.crm_staff('attendance',jsonb_build_object('booking_id',booking2,'attendance','Absent'));
 perform public.crm_staff('attendance',jsonb_build_object('booking_id',booking2,'attendance','Present'));
 perform public.crm_staff('attendance',jsonb_build_object('booking_id',booking2,'attendance','Present'));
 if (select remaining_sessions from school_crm.memberships where id=membership)<>3 then raise exception 'Attendance did not debit exactly once';end if;
 perform public.crm_staff('attendance',jsonb_build_object('booking_id',booking2,'attendance','Absent'));
 if (select remaining_sessions from school_crm.memberships where id=membership)<>4 then raise exception 'Attendance reversal did not restore credit';end if;
 insert into crm_test_results values('Membership attendance debit is idempotent and reversible',true);
 if has_schema_privilege('anon','school_crm','usage') or has_schema_privilege('authenticated','school_crm','usage') then raise exception 'Private schema exposed';end if;
 insert into crm_test_results values('CRM tables inaccessible directly to visitors',true);
end $$;
select * from crm_test_results;
rollback;
